-- PHASE 2 · Knowledge schema — 9 tables, 34 indexes, 9 read policies
--  source: knowledge_sync/migrations/001_knowledge_schema.sql
-- ══════════════════════════════════════════════════════════════════════════
-- ValueWeave Knowledge Schema (Platform v3.0, Step 1)
-- GENERATED by knowledge_sync/generate_migration.py — do not edit by hand.
-- Re-generate after changing knowledge_sync/config.py; CI checks for drift.
--
-- WHY A SEPARATE SCHEMA
-- ---------------------
-- Three of the eight table names this framework needs — kg_skills, kg_schemes and
-- kg_relationships — already exist in `public` as admin-authored CMS tables with
-- different columns, different RLS and a different purpose. Putting the
-- projection in its own schema gives the tables their intended names while
-- guaranteeing that no existing application table is opened, and makes
--
--     drop schema knowledge cascade;
--
-- a complete rollback that cannot reach user data.
--
-- WHAT IS IN EVERY TABLE
-- ----------------------
--   sync_row_key         stable key; the primary key
--   sync_source_*        the package, dataset and row this came from
--   sync_content_hash    change detection; excludes the sync_* columns
--   sync_pending_fields  {column: sentinel} — WHICH values are unknown and WHY
--   sync_deleted_at      soft delete; rows are never removed by a sync
--
-- 8 tables. Git remains the single source of truth; this schema is a
-- read-optimised cache and may be dropped and rebuilt at any time.

create schema if not exists knowledge;
comment on schema knowledge is
  'Read-only projection of the Git knowledge repository. Written only by '
  'knowledge_sync using the service role. Never edit rows here: Git is canonical.';

-- Read access for the application.
grant usage on schema knowledge to anon, authenticated;

-- Write access for the sync, and nothing else.
--
-- An earlier version of this file said the service role "bypasses grants and RLS
-- alike" and granted it nothing. Half of that is true. Supabase's `service_role`
-- has BYPASSRLS, so it is not stopped by row-level security — but BYPASSRLS is
-- not superuser, and GRANT checks still apply. Without the line below the sync
-- fails on its first statement with
--
--     permission denied for schema knowledge
--
-- on SELECT as well as INSERT. PostgreSQL only exempts superusers from privilege
-- checks, and Supabase's service role is deliberately not one. Supabase's own
-- default grants cover `public`; a schema created by a migration gets none.
grant usage on schema knowledge to service_role;


